# ---------------------------------------------------------------- evaluator
M39 = (1 << 39) - 1
CODE = [(1 << (3 * (c >> 2))) | (1 << (40 + 4 * (c & 3))) for c in range(52)]
RBIT = [1 << (c >> 2) for c in range(52)]
CBIT = [1 << c for c in range(52)]


def _straight_top(mask):
    ext = ((mask << 1) | ((mask >> 12) & 1)) & 0x3FFF
    for top in range(13, 3, -1):
        need = 0x1F << (top - 4)
        if ext & need == need:
            return top - 1
    return -1


def _nf_value(counts):
    mask = 0
    for r in range(13):
        if counts[r]:
            mask |= 1 << r
    st = _straight_top(mask)
    quads = [r for r in range(12, -1, -1) if counts[r] == 4]
    trips = [r for r in range(12, -1, -1) if counts[r] == 3]
    pairs = [r for r in range(12, -1, -1) if counts[r] == 2]
    singles = [r for r in range(12, -1, -1) if counts[r] == 1]
    if quads:
        q = quads[0]
        k = max([r for r in range(13) if counts[r] and r != q])
        return (7 << 20) | (q << 16) | (k << 12)
    if trips and (len(trips) >= 2 or pairs):
        t = trips[0]
        p = max(([trips[1]] if len(trips) > 1 else []) + pairs)
        return (6 << 20) | (t << 16) | (p << 12)
    if st >= 0:
        return (4 << 20) | (st << 16)
    if trips:
        t = trips[0]
        ks = sorted([r for r in range(13) if counts[r] and r != t], reverse=True)[:2]
        return (3 << 20) | (t << 16) | (ks[0] << 12) | (ks[1] << 8)
    if len(pairs) >= 2:
        p1, p2 = pairs[0], pairs[1]
        k = max([r for r in range(13) if counts[r] and r != p1 and r != p2])
        return (2 << 20) | (p1 << 16) | (p2 << 12) | (k << 8)
    if pairs:
        p = pairs[0]
        ks = singles[:3]
        return (1 << 20) | (p << 16) | (ks[0] << 12) | (ks[1] << 8) | (ks[2] << 4)
    ks = singles[:5]
    return (ks[0] << 16) | (ks[1] << 12) | (ks[2] << 8) | (ks[3] << 4) | ks[4]


def _build_eval():
    NF = {}
    for n in (5, 6, 7):
        for combo in itertools.combinations_with_replacement(range(13), n):
            counts = [0] * 13
            ok = True
            for r in combo:
                counts[r] += 1
                if counts[r] > 4:
                    ok = False
                    break
            if ok:
                key = 0
                for r in range(13):
                    key += counts[r] << (3 * r)
                NF[key] = _nf_value(counts)
    FL = [0] * 8192
    for mask in range(8192):
        if bin(mask).count('1') < 5:
            continue
        st = _straight_top(mask)
        if st >= 0:
            FL[mask] = (8 << 20) | (st << 16)
        else:
            rs = [r for r in range(12, -1, -1) if mask >> r & 1][:5]
            FL[mask] = (5 << 20) | (rs[0] << 16) | (rs[1] << 12) | (rs[2] << 8) | (rs[3] << 4) | rs[4]
    # straight-draw table: number of distinct ranks completing a straight (0 none, 1 gutshot, 2+ open)
    wins = [0x100F] + [0x1F << i for i in range(9)]
    SD = bytearray(8192)
    for mask in range(8192):
        if _straight_top(mask) >= 0:
            continue
        comp = 0
        for w in wins:
            miss = w & ~mask
            if miss and miss & (miss - 1) == 0:
                comp |= miss
        SD[mask] = min(2, bin(comp).count('1'))
    return NF, FL, SD


NF, FL, SD = _build_eval()


def flush_val(cards):
    cnt = [0, 0, 0, 0]
    for c in cards:
        cnt[c & 3] += 1
    su = cnt.index(max(cnt))
    m = 0
    for c in cards:
        if c & 3 == su:
            m |= RBIT[c]
    return FL[m]


def evaluate(cards):
    x = 0
    for c in cards:
        x += CODE[c]
    if ((x >> 40) + 0x3333) & 0x8888:
        return flush_val(cards)
    return NF[x & M39]


# ---------------------------------------------------------------- preflop tables
def _cls_list():
    out = []
    for i in range(13):
        for j in range(13):
            out.append((i, j))
    return out


def hand_class(a, b):
    ra, rb = a >> 2, b >> 2
    if ra < rb:
        ra, rb = rb, ra
    if ra == rb or (a & 3) == (b & 3):
        return ra * 13 + rb
    return rb * 13 + ra


def _combos(ci):
    i, j = divmod(ci, 13)
    res = []
    if i == j:
        for s1 in range(4):
            for s2 in range(s1 + 1, 4):
                res.append((i * 4 + s1, i * 4 + s2))
    elif i > j:
        for s in range(4):
            res.append((i * 4 + s, j * 4 + s))
    else:
        for s1 in range(4):
            for s2 in range(4):
                if s1 != s2:
                    res.append((j * 4 + s1, i * 4 + s2))
    return res


COMBOS = [_combos(c) for c in range(169)]
NCOMBO = [len(x) for x in COMBOS]


def _load_tables():
    raw = zlib.decompress(base64.b64decode(_DATA))
    hu = [[raw[a * 169 + b] / 255.0 for b in range(169)] for a in range(169)]
    off = 169 * 169
    multi = []
    for a in range(169):
        row = []
        for k in range(7):
            p = off + (a * 7 + k) * 2
            row.append((raw[p] * 256 + raw[p + 1]) / 65535.0)
        multi.append(row)
    return hu, multi


HU, MULTI = _load_tables()
_score = [MULTI[c][0] * 2 * 0.5 + MULTI[c][2] * 4 * 0.5 for c in range(169)]
ORDER = sorted(range(169), key=lambda c: -_score[c])
POS = [0] * 169
for _k, _c in enumerate(ORDER):
    POS[_c] = _k
GCUM = [0.0]  # global cumulative combos along ORDER, as fraction of 1326
for _c in ORDER:
    GCUM.append(GCUM[-1] + NCOMBO[_c] / 1326.0)
PCT = [(GCUM[POS[c]] + GCUM[POS[c] + 1]) / 2 for c in range(169)]  # 0 = best


def _cum_tables():
    CW = []
    CE = []
    for h in range(169):
        a, b = COMBOS[h][0]
        cw = [0.0]
        ce = [0.0]
        row = HU[h]
        for c in ORDER:
            n = 0
            for (x, y) in COMBOS[c]:
                if x != a and x != b and y != a and y != b:
                    n += 1
            cw.append(cw[-1] + n)
            ce.append(ce[-1] + n * row[c])
        CW.append(cw)
        CE.append(ce)
    return CW, CE


CW, CE = _cum_tables()


def _pos_of(x):
    # fractional index into ORDER for top-x fraction of hands
    if x <= 0:
        return 0.0
    if x >= 1:
        return 169.0
    lo, hi = 0, 169
    while hi - lo > 1:
        m = (lo + hi) >> 1
        if GCUM[m] <= x:
            lo = m
        else:
            hi = m
    span = GCUM[lo + 1] - GCUM[lo]
    return lo + ((x - GCUM[lo]) / span if span > 0 else 0.0)


def _interp(arr, p):
    i = int(p)
    if i >= 169:
        return arr[169]
    f = p - i
    return arr[i] + (arr[i + 1] - arr[i]) * f


def eq_band(h, lo, hi):
    """Heads-up equity of class h vs hands whose percentile is in [lo, hi) (0 = best)."""
    if hi - lo < 0.004:
        hi = min(1.0, lo + 0.004)
        lo = max(0.0, hi - 0.004)
    pa, pb = _pos_of(lo), _pos_of(hi)
    w = _interp(CW[h], pb) - _interp(CW[h], pa)
    if w <= 1e-9:
        return 0.5
    return (_interp(CE[h], pb) - _interp(CE[h], pa)) / w


def eq_top(h, x):
    return eq_band(h, 0.0, max(0.004, min(1.0, x)))


def combine_eq(eqs):
    """Approximate multiway equity from heads-up equities vs each opponent."""
    s = 1.0
    for e in eqs:
        e = min(0.995, max(0.005, e))
        s += (1 - e) / e
    return 1.0 / s


# ---------------------------------------------------------------- ICM-ish chip value
def chip_value(me, others):
    """Expected points (up to a constant) under a pairwise/Harville-style approximation of the
    10/7/5/4/3/2/1/0 payout: E[#players outlasted] + 3 P(1st) + P(2nd)."""
    if me <= 0:
        return 0.0
    S = me
    for s in others:
        S += s
    v = 3.0 * me / S
    for s in others:
        if s > 0:
            v += me / (me + s)
            if S - s > 0:
                v += (s / S) * (me / (S - s))
        else:
            v += 1.0
    return v


from math import exp as _exp
from bisect import bisect_right as _bisect


def _sig(z):
    if z > 8:
        return 1.0
    if z < -8:
        return 0.0
    return 1.0 / (1.0 + _exp(-z))


# ---------------------------------------------------------------- opponent model
PRIORS = {
    # name: (prior rate per outcome index list, strength)
    'open': ((0.80, 0.05, 0.15), 8),    # fold / limp / raise when unopened
    'openE': ((0.85, 0.04, 0.11), 5),   # unopened with 4+ players behind
    'openL': ((0.70, 0.05, 0.25), 5),   # unopened with <=3 players behind
    'vs1': ((0.70, 0.20, 0.10), 8),     # fold / call / 3bet facing one raise
    'vs2': ((0.75, 0.15, 0.10), 6),     # facing 3bet+
    'f3b': ((0.55, 0.30, 0.15), 5),     # opener facing a 3bet
    'allin': ((0.75, 0.25, 0.0), 3),    # facing an all-in: fold / call
    'shove': ((0.95, 0.05, 0.0), 3),    # unopened: not-shove / shove
    'bet': ((0.60, 0.40, 0.0), 8),      # checked to / first: check / bet
    'cbet': ((0.40, 0.60, 0.0), 6),
    'bet1': ((0.55, 0.45, 0.0), 6),
    'bet2': ((0.62, 0.38, 0.0), 6),
    'bet3': ((0.65, 0.35, 0.0), 6),     # preflop aggressor on flop: check / bet
    'fb': ((0.45, 0.43, 0.12), 8),      # facing bet: fold / call / raise
    'fbme': ((0.45, 0.43, 0.12), 6),    # facing OUR bet (shrinks to fb)
    'fr': ((0.50, 0.40, 0.10), 5),      # facing a raise postflop
}


class Opp(object):
    __slots__ = ('st', 'sizes', 'nsize', 'sd_agg', 'sd_bluff', 'sd_pre_n', 'sd_pre_sum', 'hands')

    def __init__(self):
        self.st = {}
        self.sizes = 0.0
        self.nsize = 0
        self.sd_agg = 0
        self.sd_bluff = 0
        self.sd_pre_n = 0
        self.sd_pre_sum = 0.0
        self.hands = 0

    def add(self, name, bucket, outcome):
        for key in ((name, -1), (name, bucket)):
            v = self.st.get(key)
            if v is None:
                v = [0, 0, 0, 0]
                self.st[key] = v
            v[0] += 1
            v[1 + outcome] += 1

    def rate(self, name, outcome, bucket=-1, parent=None):
        pri, k = PRIORS[name]
        k = k * PRIOR_SCALE
        p = pri[outcome]
        if parent is not None:
            p = parent
        v = self.st.get((name, -1))
        if v:
            p = (v[1 + outcome] + k * p) / (v[0] + k)
        if bucket >= 0:
            vb = self.st.get((name, bucket))
            if vb and v and vb[0] < v[0]:
                p = (vb[1 + outcome] + 5 * p) / (vb[0] + 5)
        return p

    def n(self, name):
        v = self.st.get((name, -1))
        return v[0] if v else 0


# ---------------------------------------------------------------- hand tracker (history replay)
class Tracker(object):
    def __init__(self, obs, me, n):
        self.n = n
        self.me = me
        self.hand_no = obs.hand_no
        self.valid = obs.street == 0
        self.processed = 0
        sb, bb = obs.blinds
        self.bb = bb
        start = [obs.stacks[i] + obs.bets[i] for i in range(n)]
        self.start = start
        dealt = [start[i] > 0 or obs.in_hand[i] for i in range(n)]
        self.dealt = dealt
        nd = sum(dealt)
        self.ndealt = nd
        self.bucket = 0 if nd >= 5 else (1 if nd >= 3 else 2)
        btn = obs.button

        def nxt(s):
            for k in range(1, n + 1):
                j = (s + k) % n
                if dealt[j]:
                    return j
            return s
        if nd == 2:
            sbs = btn if dealt[btn] else nxt(btn)
        else:
            sbs = nxt(btn)
        bbs = nxt(sbs)
        self.sbs, self.bbs = sbs, bbs
        self.stacks = list(start)
        self.bets = [0] * n
        self.in_hand = list(dealt)
        self.pot = 0
        self.street = 0
        self.max_bet = 0
        self.last_inc = bb
        self.acted = [False] * n
        self.nraise = 0
        self.aggr = -1
        self.prev_aggr = -1
        self.pre_aggr = -1
        self.first_raiser = -1
        self.pre_line = {}      # seat -> (kind, nraise_before, allin)
        self.open_late = {}     # seat -> opened with <=3 players behind
        self.lines = {}         # (seat, street) -> strongest action kind on that street
        self.last_size = {}     # seat -> last bet size as fraction of pot
        self.voluntary = False
        self.done_first = set()
        self.my_last_aggr = None  # (street) of our last bet/raise
        self.my_acted_after = False
        self.finished = False
        self.posts_checked = False
        # post blinds
        for s, amt in ((sbs, sb), (bbs, bb)):
            a = min(amt, self.stacks[s])
            self.stacks[s] -= a
            self.bets[s] += a
        self.max_bet = max(self.bets)
        self.sbamt = self.bets[sbs]
        self.bbamt = self.bets[bbs]

    def street_complete(self):
        can = [i for i in range(self.n) if self.in_hand[i] and self.stacks[i] > 0]
        if sum(self.in_hand) <= 1:
            return True
        for i in can:
            if not self.acted[i] or self.bets[i] < self.max_bet:
                if len(can) == 1 and self.bets[i] >= self.max_bet:
                    continue
                return False
        return True

    def advance(self):
        self.pot += sum(self.bets)
        self.bets = [0] * self.n
        self.max_bet = 0
        self.last_inc = self.bb
        self.acted = [False] * self.n
        if self.street == 0:
            self.pre_aggr = self.aggr
        self.prev_aggr = self.aggr
        self.aggr = -1
        self.nraise = 0
        self.street += 1
        self.done_first = set()


def is_post(kind):
    return kind not in ('fold', 'check', 'call', 'raise')


# ---------------------------------------------------------------- the bot
class Bot(Agent):
    K_OPEN = 0.9    # opening-range width multiplier
    K_FOLD = 1.0    # multiplier on modelled fold probabilities (bluff appetite)
    K_CALL = 0.025  # extra equity demanded to call
    K_SHOVE_PRIOR = 3.0  # prior strength for shove / call-shove frequencies
    K_ICM = 1.0     # weight of ICM vs linear chip value in postflop / call decisions
    K_OVERLIMP = True
    K_PRE_REAL = 0.075  # lowers preflop call realization (tighter cold calls)
    K_DEADLINE = 0.00028  # seconds after act() entry at which Monte Carlo sampling stops

    def __init__(self):
        self.rng = random.Random()
        self.rng.seed(int(_perf() * 1e6) & 0xFFFFFFF)
        self.n = 8
        self.me = 0
        self.opps = [Opp() for _ in range(8)]
        self.tr = None
        self.pool_cache = None
        self.base_cache = {}

    # ------------------------------------------------------------ table/hand lifecycle
    def new_table(self, rules, seat, n_players):
        try:
            self.n = int(n_players) if n_players else 8
        except Exception:
            self.n = 8
        self.me = seat if isinstance(seat, int) else 0
        self.opps = [Opp() for _ in range(max(self.n, 10))]
        self.tr = None
        self.pool_cache = None
        self.base_cache = {}

    def hand_end(self, result):
        try:
            self._hand_end(result)
        except Exception:
            if DEBUG:
                import traceback
                ERRORS.append(traceback.format_exc())

    def _hand_end(self, result):
        tr = self.tr
        if tr is None or tr.finished:
            return
        hist = None
        shown = None
        board = None
        if isinstance(result, dict):
            for k in ('history', 'actions', 'action_history'):
                h = result.get(k)
                if isinstance(h, (list, tuple)):
                    hist = h
                    break
            for k in ('showdown', 'shown', 'hands', 'holes', 'hole_cards', 'revealed'):
                s = result.get(k)
                if isinstance(s, dict) and s:
                    shown = s
                    break
            b = result.get('board')
            if isinstance(b, (list, tuple)):
                board = b
        if hist is not None and tr.valid and len(hist) >= tr.processed:
            self._replay(hist)
        else:
            self._infer_end()
        if shown and board is not None and len(board) == 5:
            self._showdown(shown, board)
        tr.finished = True

    def _infer_end(self):
        # we bet/raised last and never acted again: before the river that means everyone folded
        tr = self.tr
        if not tr.valid or tr.my_last_aggr is None or tr.my_acted_after:
            return
        st = tr.my_last_aggr
        if st >= 3 or tr.street != st:
            return
        me = self.me
        if tr.stacks[me] == 0:
            return
        for j in range(tr.n):
            if j != me and tr.in_hand[j] and tr.stacks[j] > 0:
                self._stat_action(j, 'fold', 0, tr, inferred=True)

    def _showdown(self, shown, board):
        tr = self.tr
        for s, cards in shown.items():
            try:
                s = int(s)
                c1, c2 = int(cards[0]), int(cards[1])
            except Exception:
                continue
            if s == self.me or not (0 <= s < len(self.opps)):
                continue
            o = self.opps[s]
            pl = tr.pre_line.get(s)
            if pl and pl[0] == 'raise':
                o.sd_pre_n += 1
                o.sd_pre_sum += PCT[hand_class(c1, c2)]
            agg = tr.lines.get((s, 3)) in ('bet', 'raise') or tr.lines.get((s, 2)) in ('bet', 'raise')
            if agg:
                v = evaluate([c1, c2] + list(board))
                # strength vs random hands on this board
                used = set(board) | {c1, c2}
                deck = [c for c in range(52) if c not in used]
                rng = self.rng
                beat = 0
                for _ in range(40):
                    a, b = rng.sample(deck, 2)
                    if v >= evaluate([a, b] + list(board)):
                        beat += 1
                o.sd_agg += 1
                if beat < 24:
                    o.sd_bluff += 1

    def _start_hand(self, obs):
        if self.tr is not None and not self.tr.finished:
            try:
                self._infer_end()
            except Exception:
                pass
        n = len(obs.stacks)
        self.n = n
        if len(self.opps) < n:
            self.opps += [Opp() for _ in range(n - len(self.opps))]
        self.me = obs.seat
        self.tr = Tracker(obs, obs.seat, n)
        self.pool_cache = None
        for j in range(n):
            if self.tr.dealt[j]:
                self.opps[j].hands += 1

    # ------------------------------------------------------------ replay + stats
    def _replay(self, hist):
        tr = self.tr
        k = tr.processed
        L = len(hist)
        while k < L:
            item = hist[k]
            k += 1
            try:
                s = int(item[0])
                act = item[1]
                kind = act[0]
                amt = int(act[1]) if len(act) > 1 and act[1] is not None else 0
            except Exception:
                tr.valid = False
                break
            if not (0 <= s < tr.n):
                tr.valid = False
                break
            if not tr.voluntary and tr.street == 0 and not tr.posts_checked:
                # blind posts in history?
                if is_post(kind):
                    if amt > tr.bets[s]:
                        add = min(amt - tr.bets[s], tr.stacks[s])
                        tr.stacks[s] -= add
                        tr.bets[s] += add
                        tr.max_bet = max(tr.max_bet, tr.bets[s])
                    continue
                if k == 1 and L >= 2 and s == tr.sbs and amt == tr.sbamt and kind != 'fold' and kind != 'check':
                    nx = hist[1]
                    try:
                        if int(nx[0]) == tr.bbs and nx[1][0] != 'check' and int(nx[1][1]) == tr.bbamt:
                            k = 2
                            tr.posts_checked = True
                            continue
                    except Exception:
                        pass
                tr.posts_checked = True
            if is_post(kind):
                continue
            tr.voluntary = True
            self._apply(s, kind, amt)
        tr.processed = k

    def _apply(self, s, kind, amt):
        tr = self.tr
        if not tr.in_hand[s]:
            tr.valid = False
            return
        self._stat_action(s, kind, amt, tr)
        if s == self.me:
            if kind == 'raise':
                tr.my_last_aggr = tr.street
                tr.my_acted_after = False
            elif tr.my_last_aggr is not None:
                tr.my_acted_after = True
        elif kind != 'fold' and tr.my_last_aggr is not None and tr.street == tr.my_last_aggr:
            pass
        street = tr.street
        if kind == 'fold':
            tr.in_hand[s] = False
        elif kind == 'check':
            tr.acted[s] = True
            if (s, street) not in tr.lines:
                tr.lines[(s, street)] = 'check'
        elif kind == 'call':
            add = min(tr.max_bet - tr.bets[s], tr.stacks[s])
            if add < 0:
                add = 0
            tr.stacks[s] -= add
            tr.bets[s] += add
            tr.acted[s] = True
            if tr.lines.get((s, street)) not in ('bet', 'raise'):
                tr.lines[(s, street)] = 'call'
            if street == 0 and s not in tr.pre_line:
                tr.pre_line[s] = ('call', tr.nraise, tr.stacks[s] == 0)
        else:  # raise to amt
            add = amt - tr.bets[s]
            if add > tr.stacks[s]:
                add = tr.stacks[s]
            if add < 0:
                add = 0
            potb = tr.pot + sum(tr.bets)
            tr.stacks[s] -= add
            tr.bets[s] += add
            inc = tr.bets[s] - tr.max_bet
            if inc >= tr.last_inc:
                tr.last_inc = inc
            prevmax = tr.max_bet
            tr.max_bet = max(tr.max_bet, tr.bets[s])
            for j in range(tr.n):
                if j != s:
                    tr.acted[j] = False
            tr.acted[s] = True
            tr.lines[(s, street)] = 'raise' if prevmax > 0 and street > 0 else 'bet'
            if street == 0:
                tr.lines[(s, 0)] = 'raise'
                tr.pre_line[s] = ('raise', tr.nraise, tr.stacks[s] == 0)
                if tr.first_raiser < 0:
                    tr.first_raiser = s
            if potb > 0:
                tr.last_size[s] = (tr.bets[s] - prevmax) / float(potb + prevmax)
            tr.nraise += 1
            tr.aggr = s
        if sum(tr.in_hand) <= 1:
            return
        if tr.street_complete():
            tr.advance()

    def _stat_action(self, s, kind, amt, tr, inferred=False):
        if s == self.me or not (0 <= s < len(self.opps)):
            return
        o = self.opps[s]
        b = tr.bucket
        street = tr.street
        to_call = tr.max_bet - tr.bets[s]
        stack = tr.stacks[s]
        is_shove = kind == 'raise' and amt >= tr.bets[s] + stack
        first = s not in tr.done_first
        tr.done_first.add(s)
        if street == 0:
            if first and s not in tr.pre_line:
                if tr.nraise == 0:
                    if not (s == tr.bbs and to_call <= 0):
                        oc = 0 if kind == 'fold' else (1 if kind in ('call', 'check') else 2)
                        o.add('open', b, oc)
                        o.add('shove', b, 1 if is_shove else 0)
                        nbh = 0
                        for i in range(tr.n):
                            if i != s and tr.in_hand[i] and not tr.acted[i] and tr.stacks[i] > 0:
                                nbh += 1
                        late = nbh <= 3
                        o.add('openL' if late else 'openE', b, oc)
                        tr.open_late[s] = late
                elif tr.nraise == 1:
                    oc = 0 if kind == 'fold' else (1 if kind in ('call', 'check') else 2)
                    o.add('vs1', b, oc)
                else:
                    oc = 0 if kind == 'fold' else (1 if kind in ('call', 'check') else 2)
                    o.add('vs2', b, oc)
            elif tr.first_raiser == s and tr.nraise >= 2 and to_call > 0:
                oc = 0 if kind == 'fold' else (1 if kind == 'call' else 2)
                o.add('f3b', b, oc)
            if to_call > 0 and tr.aggr >= 0 and tr.stacks[tr.aggr] == 0 and tr.nraise >= 1:
                o.add('allin', b, 0 if kind == 'fold' else 1)
        else:
            if to_call <= 0:
                oc = 1 if kind == 'raise' else 0
                o.add('bet', b, oc)
                o.add('bet%d' % min(3, street), b, oc)
                if street == 1 and tr.pre_aggr == s and tr.nraise == 0:
                    o.add('cbet', b, oc)
                if kind == 'raise':
                    potb = tr.pot + sum(tr.bets)
                    if potb > 0:
                        o.sizes += min(3.0, amt / float(potb))
                        o.nsize += 1
            else:
                oc = 0 if kind == 'fold' else (1 if kind == 'call' else 2)
                if tr.nraise <= 1:
                    o.add('fb', b, oc)
                    if tr.aggr == self.me:
                        o.add('fbme', b, oc)
                else:
                    o.add('fr', b, oc)
                    if tr.aggr == self.me:
                        o.add('fbme', b, oc)
            if to_call > 0 and tr.aggr >= 0 and tr.stacks[tr.aggr] == 0:
                o.add('allin', b, 0 if kind == 'fold' else 1)

    # ------------------------------------------------------------ act
    def act(self, obs):
        t0 = _perf()
        try:
            a = self._act(obs, t0)
            return self._legalize(obs, a)
        except Exception:
            if DEBUG:
                import traceback
                ERRORS.append(traceback.format_exc())
            return self._safe(obs)

    def _safe(self, obs):
        try:
            if 'check' in obs.legal:
                return ('check', 0)
            if 'call' in obs.legal and obs.to_call <= max(1, (obs.pot + sum(obs.bets)) // 8):
                return ('call', 0)
            if 'fold' in obs.legal:
                return ('fold', 0)
            return (sorted(obs.legal)[0], 0)
        except Exception:
            return ('fold', 0)

    def _legalize(self, obs, a):
        kind, amt = a
        legal = obs.legal
        if kind == 'raise':
            if 'raise' not in legal:
                kind = 'call' if 'call' in legal else 'check'
                return (kind, 0) if kind in legal else self._safe(obs)
            amt = int(amt)
            if amt < obs.min_raise:
                amt = obs.min_raise
            if amt > obs.max_raise:
                amt = obs.max_raise
            # if raise is nearly all-in, just shove
            if obs.max_raise - amt < 0.12 * amt:
                amt = obs.max_raise
            return ('raise', int(amt))
        if kind == 'fold' and 'check' in legal:
            return ('check', 0)
        if kind == 'check' and 'check' not in legal:
            return ('fold', 0) if 'fold' in legal else self._safe(obs)
        if kind == 'call' and 'call' not in legal:
            return ('check', 0) if 'check' in legal else self._safe(obs)
        if kind not in legal:
            return self._safe(obs)
        return (kind, 0)

    def _act(self, obs, t0):
        self.t0 = t0
        if self.tr is None or self.tr.hand_no != obs.hand_no or self.tr.finished:
            self._start_hand(obs)
        tr = self.tr
        self.cur_obs = obs
        if tr.valid:
            try:
                self._replay(obs.history or [])
                ok = (tr.valid and tr.street == obs.street and list(tr.bets) == list(obs.bets) and
                      [bool(x) for x in tr.in_hand] == [bool(x) for x in obs.in_hand])
            except Exception:
                ok = False
            if not ok:
                self._resync(obs)
        if len(obs.legal) == 1:
            k = next(iter(obs.legal))
            return (k, obs.min_raise if k == 'raise' else 0)
        if obs.street == 0:
            return self._preflop(obs)
        return self._postflop(obs)

    def _resync(self, obs):
        """History replay disagreed with the observation: adopt the observed state and carry on."""
        tr = self.tr
        tr.resyncs = getattr(tr, 'resyncs', 0) + 1
        if tr.resyncs > 4 or len(obs.stacks) != tr.n:
            tr.valid = False
            return
        tr.valid = True
        tr.street = obs.street
        tr.bets = list(obs.bets)
        tr.stacks = list(obs.stacks)
        tr.in_hand = [bool(x) for x in obs.in_hand]
        tr.pot = obs.pot
        tr.max_bet = max(obs.bets) if obs.bets else 0
        tr.acted = [(tr.bets[i] == tr.max_bet and tr.max_bet > 0) for i in range(tr.n)]
        tr.acted[obs.seat] = False
        tr.processed = len(obs.history or [])
        tr.posts_checked = True
        tr.voluntary = True
        bb = obs.blinds[1] or 1
        lv = sorted(set(x for x in obs.bets if x > (bb if obs.street == 0 else 0)))
        tr.nraise = len(lv)
        tr.aggr = max(range(tr.n), key=lambda i: obs.bets[i]) if lv else -1
        tr.done_first = set(i for i in range(tr.n) if tr.acted[i])
        for i in range(tr.n):
            if i != obs.seat and obs.in_hand[i] and obs.street == 0 and obs.bets[i] > bb and i not in tr.pre_line:
                tr.pre_line[i] = ('raise' if obs.bets[i] == tr.max_bet else 'call', 0, obs.stacks[i] == 0)
            if i != obs.seat and obs.in_hand[i] and obs.street > 0 and obs.bets[i] > 0 and (i, obs.street) not in tr.lines:
                tr.lines[(i, obs.street)] = 'bet' if obs.bets[i] == tr.max_bet else 'call'

    # ------------------------------------------------------------ helpers
    def _ctx(self, obs):
        n = len(obs.stacks)
        me = obs.seat
        opps = [j for j in range(n) if j != me and obs.in_hand[j]]
        return n, me, opps

    def _alive_others(self, obs, me):
        return [obs.stacks[j] + obs.bets[j] for j in range(len(obs.stacks)) if j != me and
                (obs.stacks[j] > 0 or obs.in_hand[j] or obs.bets[j] > 0)]

    def _allin_decision(self, obs, eq, opp_list, extra_win=0):
        """V-units EV of calling/shoving all-in vs opp_list (seat ids) minus folding, given equity eq."""
        me = obs.seat
        n = len(obs.stacks)
        cur = obs.stacks
        bets = obs.bets
        alive = [j for j in range(n) if j != me and (cur[j] > 0 or obs.in_hand[j])]
        opp_list = [j for j in opp_list if j in alive and obs.in_hand[j]]
        pot_total = obs.pot + sum(bets)
        my_total = cur[me] + bets[me]
        others0 = [cur[j] for j in alive]
        if not opp_list:
            return 0.0
        idx0 = alive.index(opp_list[0])
        of = list(others0)
        of[idx0] += pot_total
        v_fold = chip_value(cur[me], of)
        others_win = list(others0)
        their = 0
        my_extra = 0
        for j in opp_list:
            cap = min(cur[j] + bets[j], my_total)
            te = max(0, cap - bets[j])
            others_win[alive.index(j)] -= te
            their += te
            my_extra = max(my_extra, cap - bets[me])
        my_extra = max(0, min(my_extra, cur[me]))
        v_win = chip_value(cur[me] + pot_total + their + extra_win, others_win)
        ol = list(others_win)
        ol[idx0] += pot_total + my_extra + their
        v_lose = chip_value(cur[me] - my_extra, ol)
        return eq * v_win + (1 - eq) * v_lose - v_fold

    def _pre_range(self, s):
        """Return (lo, hi, weight-top) percentile band describing seat s's preflop range."""
        tr = self.tr
        o = self.opps[s]
        b = tr.bucket if tr else 0
        pl = tr.pre_line.get(s) if tr else None
        sd_w = None
        if o.sd_pre_n >= 2:
            sd_w = min(1.0, 2.0 * o.sd_pre_sum / o.sd_pre_n)
        if pl is None:
            ob = getattr(self, 'cur_obs', None)
            if ob is not None and ob.street == 0 and ob.bets[s] > (ob.blinds[1] or 1):
                w = max(0.04, o.rate('open', 2, b))
                if sd_w is not None:
                    w = max(w, sd_w)
                return (0.0, min(1.0, w * 1.2))
            if ob is not None and tr is not None and s in (tr.bbs, tr.sbs):
                return (0.0, 0.85)
            return (0.0, 0.55)
        kind, nr, allin = pl
        if kind == 'raise':
            if nr == 0:
                w = o.rate('open', 2, b)
                lt = tr.open_late.get(s)
                if lt is not None:
                    w = o.rate('openL' if lt else 'openE', 2, b, parent=min(0.95, w * (1.45 if lt else 0.7)))
                if allin:
                    w = max(o.rate('shove', 1, b), 0.03)
            elif nr == 1:
                w = o.rate('vs1', 2, b)
            else:
                w = o.rate('vs2', 2, b) * 0.6
            if allin:
                w = max(w, o.rate('shove', 1, b))
            if sd_w is not None:
                w = max(w, sd_w)
            return (0.0, max(0.02, min(1.0, w)))
        # called
        if nr == 0:
            lo = o.rate('open', 2, b) * 0.6
            return (lo, min(1.0, lo + max(0.15, o.rate('open', 1, b) * 1.2) + 0.1))
        if nr == 1:
            r = o.rate('vs1', 2, b)
            c = o.rate('vs1', 1, b)
            if s == tr.bbs:
                c = min(1.0, c * 1.6 + 0.1)
            return (r * 0.5, min(1.0, r + c + 0.05))
        r = o.rate('vs2', 2, b)
        c = o.rate('vs2', 1, b)
        return (r * 0.4, min(1.0, r + c + 0.03))

    # ------------------------------------------------------------ preflop
    def _preflop(self, obs):
        n, me, opps = self._ctx(obs)
        bb = obs.blinds[1] or 1
        h = hand_class(obs.hole[0], obs.hole[1])
        pct = PCT[h]
        my_total = obs.stacks[me] + obs.bets[me]
        to_call = obs.to_call
        pot_total = obs.pot + sum(obs.bets)
        tr = self.tr
        b = tr.bucket if tr else 0
        rng = self.rng
        opp_tot = [obs.stacks[j] + obs.bets[j] for j in opps]
        eff = min(my_total, max(opp_tot) if opp_tot else my_total)
        eff_bb = eff / float(bb)
        max_bet = max(obs.bets)
        # count voluntary raises
        if tr.valid:
            nraise = tr.nraise
            aggr = tr.aggr
        else:
            nraise = 0
            aggr = -1
            for (s, a) in obs.history or []:
                if a[0] == 'raise' and a[1] > bb:
                    nraise += 1
                    aggr = s
            if nraise == 0 and max_bet > bb:
                nraise = 1
            if aggr < 0 and nraise:
                aggr = max(opps, key=lambda j: obs.bets[j]) if opps else -1
        # players still to act behind us (not yet acted this round)
        if tr.valid:
            behind = [j for j in opps if obs.stacks[j] > 0 and not tr.acted[j]]
        else:
            behind = [j for j in opps if obs.bets[j] < max_bet or (nraise == 0 and obs.bets[j] <= bb)]
        n_dealt = tr.ndealt if tr else len(opps) + 1
        if nraise == 0:
            return self._unopened(obs, h, pct, eff_bb, behind, my_total, pot_total, b)
        return self._facing_raise(obs, h, pct, eff_bb, aggr, nraise, behind, my_total, pot_total, b)

    def _call_width_vs_shove(self, j, shove_bb, b):
        o = self.opps[j]
        prior = min(0.6, max(0.05, 0.22 * (10.0 / max(1.0, shove_bb)) ** 0.6))
        vp = 1.0 - o.rate('open', 0, b)  # how loose they are
        prior *= max(0.6, min(2.0, (vp / 0.2) ** 0.5))
        v = o.st.get(('allin', -1))
        if v:
            prior = (v[2] + 3 * prior) / (v[0] + 3)
        if o.sd_pre_n >= 2:
            prior = max(prior, min(0.9, o.sd_pre_sum / o.sd_pre_n))
        return min(0.95, max(0.03, prior))

    def _shove_ev(self, obs, h, behind, b):
        """V-units EV of shoving now minus folding; behind = seats yet to act."""
        me = obs.seat
        n = len(obs.stacks)
        bb = obs.blinds[1] or 1
        my_total = obs.stacks[me] + obs.bets[me]
        pot_total = obs.pot + sum(obs.bets)
        cur = list(obs.stacks)
        others_idx = [j for j in range(n) if j != me and (cur[j] > 0 or obs.in_hand[j] or obs.bets[j] > 0)]
        v_fold = chip_value(cur[me], [cur[j] for j in others_idx])
        # all fold: we win pot
        others = [cur[j] for j in others_idx]
        v_steal = chip_value(cur[me] + pot_total, others)
        p_nocall = 1.0
        ev = 0.0
        for j in behind:
            ctot = obs.stacks[j] + obs.bets[j]
            risk_bb = min(my_total, ctot) / float(bb)
            q = self._call_width_vs_shove(j, risk_bb, b)
            e = eq_top(h, q)
            pj = p_nocall * q
            cap = min(my_total, ctot)
            my_extra = cap - obs.bets[me]
            their_extra = cap - obs.bets[j]
            k = others_idx.index(j)
            ow = list(others)
            ow[k] -= their_extra
            v_w = chip_value(cur[me] + pot_total + their_extra, ow)
            ol = list(others)
            ol[k] += pot_total + my_extra - 0
            ol[k] -= 0
            v_l = chip_value(cur[me] - my_extra, ol)
            ev += pj * (e * v_w + (1 - e) * v_l)
            p_nocall *= (1 - q)
        ev += p_nocall * v_steal
        return ev - v_fold, p_nocall

    def _unopened(self, obs, h, pct, eff_bb, behind, my_total, pot_total, b):
        me = obs.seat
        bb = obs.blinds[1] or 1
        to_call = obs.to_call
        rng = self.rng
        nb = len(behind)
        # BB option (limped / walk)
        if to_call == 0:
            limpers = sum(1 for j in range(len(obs.stacks)) if j != me and obs.in_hand[j])
            if pct < 0.10 or (pct < 0.18 and limpers <= 1 and rng.random() < 0.5):
                if eff_bb <= 12:
                    return ('raise', obs.max_raise)
                return ('raise', int(obs.bets[me] + (3.0 + limpers) * bb))
            return ('check', 0)
        limpers = sum(1 for j in range(len(obs.stacks)) if j != me and obs.bets[j] >= bb and j not in behind)
        # push / fold regime
        if eff_bb <= 14:
            ev, pnc = self._shove_ev(obs, h, behind, b)
            if ev > 0:
                return ('raise', obs.max_raise)
            # SB complete vs BB with a playable hand when shove is marginal? keep simple
            if to_call <= 0.5 * bb and nb == 1 and pct < 0.55 and eff_bb > 8:
                return ('call', 0)
            return ('fold', 0)
        # opening range by players behind, widened when the players behind fold a lot
        base = {0: 1.0, 1: 0.52, 2: 0.42, 3: 0.30, 4: 0.24, 5: 0.20, 6: 0.17}.get(nb, 0.14)
        if b == 1:
            base *= 1.1
        fold_prob = 1.0
        prior_fp = 1.0
        for j in behind:
            o = self.opps[j]
            d = 1.0 - o.rate('vs1', 0, b)
            if j == (self.tr.bbs if self.tr else -1):
                d = min(0.95, d * 1.4)
            fold_prob *= (1 - d)
            prior_fp *= (1 - (0.30 * (1.4 if j == (self.tr.bbs if self.tr else -1) else 1.0)))
        ratio = (fold_prob + 0.05) / (prior_fp + 0.05)
        w = base * max(0.6, min(1.8, ratio ** 0.6))
        if limpers:
            w = min(w, 0.12 + 0.03 * (nb <= 2))
        w = max(0.05, min(0.85, w * self.K_OPEN))
        if pct < w:
            if eff_bb <= 20 and pct > 0.06:
                ev, pnc = self._shove_ev(obs, h, behind, b)
                if ev > 0:
                    return ('raise', obs.max_raise)
            size = 2.25 * bb + limpers * bb
            if nb == 1 and self.tr and me == self.tr.sbs:
                size = 2.8 * bb
            if eff_bb < 25:
                size = 2.0 * bb + limpers * bb
            return ('raise', int(size))
        # over-limp behind limpers with hands that realise well multiway (pairs, suited, connected) when deep
        if limpers and eff_bb >= 25 and to_call <= bb:
            hi_r, lo_r = divmod(h, 13)
            spec = hi_r == lo_r or hi_r > lo_r or abs(hi_r - lo_r) == 1
            if spec and pct < 0.42 and self.K_OVERLIMP:
                return ('call', 0)
        # open-limp only from the SB with decent hands when deep vs a passive BB
        if self.tr and me == self.tr.sbs and nb == 1 and pct < 0.45:
            return ('call', 0)
        return ('fold', 0)

    def _resteal_ev(self, obs, h, aggr, ranges, behind, b):
        """V-units EV of an all-in reraise over an open, minus folding."""
        me = obs.seat
        bb = obs.blinds[1] or 1
        n = len(obs.stacks)
        my_total = obs.stacks[me] + obs.bets[me]
        pot_total = obs.pot + sum(obs.bets)
        alive = [k for k in range(n) if k != me and (obs.stacks[k] > 0 or obs.in_hand[k])]
        others = [obs.stacks[k] for k in alive]
        v_fold = chip_value(obs.stacks[me], others)
        v_steal = chip_value(obs.stacks[me] + pot_total, others)
        p_all_fold = 1.0
        ev = 0.0
        cands = [r[0] for r in ranges] + [j for j in behind if j not in [r[0] for r in ranges]]
        for j in cands:
            jt = obs.stacks[j] + obs.bets[j]
            risk_bb = min(my_total, jt) / float(bb)
            cw = self._call_width_vs_shove(j, risk_bb, b)
            if j in [r[0] for r in ranges]:
                lo, hi = [(r[1], r[2]) for r in ranges if r[0] == j][0]
                # committed raisers call wider
                commit = obs.bets[j] / float(max(1, jt))
                cw = min(hi, max(cw, hi * min(1.0, 0.35 + commit * 1.5)))
                pc = cw / max(hi, 1e-6)
            else:
                pc = cw
            pc = max(0.0, min(1.0, pc))
            e = eq_top(h, cw)
            cap = min(my_total, jt)
            my_extra = max(0, cap - obs.bets[me])
            their_extra = max(0, cap - obs.bets[j])
            k = alive.index(j) if j in alive else -1
            if k < 0:
                continue
            ow = list(others)
            ow[k] -= their_extra
            v_w = chip_value(obs.stacks[me] + pot_total + their_extra, ow)
            ol = list(others)
            ol[k] += pot_total + my_extra
            v_l = chip_value(obs.stacks[me] - my_extra, ol)
            ev += p_all_fold * pc * (e * v_w + (1 - e) * v_l)
            p_all_fold *= (1 - pc)
        ev += p_all_fold * v_steal
        return ev - v_fold

    def _facing_raise(self, obs, h, pct, eff_bb, aggr, nraise, behind, my_total, pot_total, b):
        me = obs.seat
        bb = obs.blinds[1] or 1
        to_call = obs.to_call
        rng = self.rng
        n = len(obs.stacks)
        opps = [j for j in range(n) if j != me and obs.in_hand[j]]
        # ranges of everyone who has put money in voluntarily
        ranges = []
        allin_opps = []
        for j in opps:
            if obs.bets[j] > bb or (self.tr and self.tr.valid and self.tr.pre_line.get(j)):
                lo, hi = self._pre_range(j)
                ranges.append((j, lo, hi))
                if obs.stacks[j] == 0:
                    allin_opps.append(j)
        if not ranges and aggr >= 0:
            ranges = [(aggr, 0.0, 0.2)]
        eqs = []
        for (j, lo, hi) in ranges:
            if lo > 0:
                # callers: weight band but keep some top hands
                e = 0.7 * eq_band(h, lo, hi) + 0.3 * eq_top(h, hi)
            else:
                e = eq_top(h, hi)
            eqs.append(e)
        e_main = combine_eq(eqs) if eqs else 0.5
        e_aggr = eqs[[r[0] for r in ranges].index(aggr)] if aggr in [r[0] for r in ranges] else e_main
        needed = to_call / float(max(1, pot_total + to_call))
        # big decision: call puts in a large part of the stack or facing all-in
        commit = to_call >= 0.33 * my_total or bool(allin_opps) and to_call >= 0.2 * my_total
        if commit or eff_bb <= 12:
            # option A: shove (if raise legal and others not all-in) ; option B: call ; option C: fold
            # equity when called is vs their range (they call a shove with most of their range when committed)
            ev_call = self._allin_decision(obs, e_main, [r[0] for r in ranges] or ([aggr] if aggr >= 0 else []))
            # behind players can still wake up: small penalty
            ev_call -= 0.04 * len(behind)
            if 'raise' in obs.legal and not allin_opps:
                # fold equity of a shove vs aggressor
                o = self.opps[aggr] if aggr >= 0 else None
                fe = 0.0
                if o is not None:
                    contf = 1.0 - (o.rate('f3b', 0, b) if nraise == 1 else 0.3)
                    a_tot = obs.stacks[aggr] + obs.bets[aggr]
                    commit_frac = obs.bets[aggr] / float(max(1, a_tot))
                    fe = max(0.0, min(0.8, (1 - contf) * (1 - commit_frac) ** 1.5))
                ev_sh = (1 - fe) * self._allin_decision(obs, e_main * 0.97, [r[0] for r in ranges]) + \
                    fe * (chip_value(obs.stacks[me] + pot_total, [obs.stacks[j] for j in range(n) if j != me and (obs.stacks[j] > 0 or obs.in_hand[j])]) -
                          chip_value(obs.stacks[me], [obs.stacks[j] for j in range(n) if j != me and (obs.stacks[j] > 0 or obs.in_hand[j])]))
                ev_sh -= 0.04 * len(behind)
                if ev_sh > 0 and ev_sh >= ev_call:
                    return ('raise', obs.max_raise)
            if ev_call > 0:
                return ('call', 0)
            return ('fold', 0)
        # resteal: shove over a single open with 12-25bb when fold equity + equity when called pays
        if nraise == 1 and eff_bb <= 25 and 'raise' in obs.legal and aggr >= 0 and not allin_opps and len(ranges) <= 2:
            ev_rs = self._resteal_ev(obs, h, aggr, ranges, behind, b)
            if ev_rs > 0.01:
                return ('raise', obs.max_raise)
        # deep(er) stacks
        ip = not behind and (self.tr is None or me != self.tr.bbs and me != self.tr.sbs)
        in_bb = self.tr is not None and me == self.tr.bbs
        realize = (0.86 if ip else (0.78 if in_bb else 0.70)) - self.K_PRE_REAL
        i, j = divmod(h, 13)
        if eff_bb > 40 and (i == j or i > j):
            realize += 0.06
        if len(ranges) >= 2:
            realize -= 0.04
        o = self.opps[aggr] if aggr >= 0 else Opp()
        value_thr = 0.60 if nraise == 1 else 0.62
        cur_raise = max(obs.bets)
        if e_aggr >= value_thr and e_main >= 0.42 and 'raise' in obs.legal:
            mult = 3.0 if ip else 3.6
            if nraise >= 2:
                mult = 2.3
            size = cur_raise * mult + (len(ranges) - 1) * cur_raise
            if size >= 0.38 * my_total:
                return ('raise', obs.max_raise)
            return ('raise', int(size))
        # light 3bets vs openers who over-fold to 3bets
        if nraise == 1 and len(ranges) == 1 and 'raise' in obs.legal and eff_bb >= 30:
            f3 = o.rate('f3b', 0, b)
            if f3 > 0.55 and 0.08 < pct < 0.4 and (i > j or h % 13 == 12 or i == j):
                if rng.random() < min(0.6, (f3 - 0.5) * 2):
                    size = cur_raise * (3.0 if ip else 3.6)
                    if size < 0.38 * my_total:
                        return ('raise', int(size))
        q = max(0.0, e_main * realize + 0.01 - self.K_CALL)
        jv = aggr if aggr >= 0 else (ranges[0][0] if ranges else -1)
        VV = self._valuer(obs, jv)
        s0 = obs.stacks[me]
        x = min(to_call, s0)
        if q * VV(s0 + pot_total, 0) + (1 - q) * VV(s0 - x, pot_total + x) >= VV(s0, pot_total):
            return ('call', 0)
        # set-mine / suited speculative calls with good implied odds
        if eff_bb > 50 and to_call <= 0.06 * my_total and (i == j or (i > j and abs(i - j) <= 2)) and \
                e_main * realize >= needed - 0.08:
            return ('call', 0)
        return ('fold', 0)

    # ------------------------------------------------------------ postflop
    def _base_hands(self, obs, j, N, known_mask):
        """Hands sampled from seat j's preflop range (cached per hand; board conflicts filtered later)."""
        bc = self.base_cache
        if bc.get('hand') != obs.hand_no:
            bc.clear()
            bc['hand'] = obs.hand_no
        hs = bc.get(j)
        if hs is not None and len(hs) >= N:
            return hs
        lo, hi = self._pre_range(j) if self.tr else (0.0, 0.55)
        m_top = 0.35 * lo
        m_band = hi - lo
        m_bot = 0.04 * (1.0 - hi)
        tot = m_top + m_band + m_bot
        hs = []
        R = _rand
        tries = 0
        while len(hs) < N and tries < 3 * N:
            tries += 1
            u = R() * tot
            if u < m_band:
                p = lo + u
            elif u < m_band + m_top:
                p = (u - m_band) / 0.35
            else:
                p = hi + (u - m_band - m_top) / 0.04
            k = _bisect(GCUM, p) - 1
            if k < 0:
                k = 0
            elif k > 168:
                k = 168
            cl = COMBOS[ORDER[k]]
            x, y = cl[int(R() * len(cl))]
            if known_mask >> x & 1 or known_mask >> y & 1:
                continue
            hs.append((x, y))
        bc[j] = hs
        return hs

    def _build_pools(self, obs, opps, known_mask):
        """Per opponent: entries (x, y, code_with_board, cardmask, strength_pct, made_value); cached per street."""
        key = (obs.hand_no, obs.street, tuple(opps))
        pc = self.pool_cache
        if pc is not None and pc[0] == key:
            return pc[1]
        board = obs.board
        bl = list(board)
        bcode = 0
        bmask_r = 0
        for c in board:
            bcode += CODE[c]
            bmask_r |= RBIT[c]
        street = obs.street
        nop = len(opps)
        N = 52 if nop == 1 else (30 if nop == 2 else max(12, 60 // nop))
        pools = {}
        for j in opps:
            hands = self._base_hands(obs, j, N, known_mask)
            vals = []
            for (x, y) in hands:
                if known_mask >> x & 1 or known_mask >> y & 1:
                    continue
                xx = bcode + CODE[x] + CODE[y]
                if ((xx >> 40) + 0x3333) & 0x8888:
                    v = flush_val([x, y] + bl)
                else:
                    v = NF[xx & M39]
                draw = 0.0
                if street < 3:
                    sc = xx >> 40
                    sx = x & 3
                    sy = y & 3
                    fd = ((sc >> (4 * sx)) & 15) == 4 or ((sc >> (4 * sy)) & 15) == 4
                    sd = SD[bmask_r | RBIT[x] | RBIT[y]] if v < 4194304 else 0
                    if fd and sd:
                        draw = 0.85 if street == 1 else 0.7
                    elif fd or sd >= 2:
                        draw = 0.68 if street == 1 else 0.55
                    elif sd == 1:
                        draw = 0.45 if street == 1 else 0.35
                vals.append((v, draw, x, y))
            vals.sort()
            m = len(vals)
            entries = []
            for rnk in range(m):
                v, draw, x, y = vals[rnk]
                p = (rnk + 0.5) / m
                if draw > p:
                    p = 0.5 * (p + draw) if p > 0.5 else draw
                entries.append((x, y, bcode + CODE[x] + CODE[y], CBIT[x] | CBIT[y], p, v))
            pools[j] = entries
        self.pool_cache = (key, pools)
        return pools

    def _line_weights(self, obs, j, entries):
        """Weights of each pool entry given seat j's postflop actions this hand."""
        tr = self.tr
        o = self.opps[j]
        b = tr.bucket if tr else 0
        street = obs.street
        w = [1.0] * len(entries)
        bl = 0.22
        if o.sd_agg >= 2:
            bl = max(0.08, min(0.85, (o.sd_bluff + 0.25 * 3) / (o.sd_agg + 3)))
        acts = []
        if tr and tr.valid:
            for s in range(1, street + 1):
                ln = tr.lines.get((j, s))
                if ln:
                    acts.append((s, ln))
        else:
            if obs.bets[j] > 0 and obs.bets[j] == max(obs.bets):
                acts.append((street, 'bet'))
        if not acts:
            return w
        for (s, ln) in acts:
            soft = 0.07 if s == street else 0.13
            if ln == 'bet':
                t = o.rate('bet%d' % min(3, s), 1, b, parent=o.rate('bet', 1, b))
                if s == street and o.nsize >= 3 and j in tr.last_size if tr else False:
                    avg = o.sizes / o.nsize
                    ratio = tr.last_size[j] / max(0.1, avg)
                    t *= max(0.5, min(1.4, ratio ** -0.5))
                t = max(0.15, min(0.9, t * 1.1))
                thr = 1 - t
                bw = bl
            elif ln == 'raise':
                t = max(0.06, min(0.6, o.rate('fb', 2, b) * 1.5))
                thr = 1 - t
                bw = bl * 0.8
            elif ln == 'call':
                t = max(0.25, min(0.95, 1 - o.rate('fb', 0, b)))
                thr = 1 - t
                bw = 0.12
            else:  # check
                t = o.rate('bet', 1, b)
                thr = 1 - t * 0.6
                for k in range(len(entries)):
                    p = entries[k][4]
                    w[k] *= 1.0 - 0.6 * _sig((p - thr) / soft)
                continue
            for k in range(len(entries)):
                p = entries[k][4]
                w[k] *= bw + (1 - bw) * _sig((p - thr) / soft)
        return w

    def _postflop(self, obs):
        n, me, opps = self._ctx(obs)
        t0 = self.t0
        rng = self.rng
        bb = obs.blinds[1] or 1
        hole = obs.hole
        board = tuple(obs.board)
        street = obs.street
        to_call = obs.to_call
        pot_total = obs.pot + sum(obs.bets)
        my_stack = obs.stacks[me]
        tr = self.tr
        b = tr.bucket if tr else 0
        known_mask = 0
        for c in hole:
            known_mask |= CBIT[c]
        for c in board:
            known_mask |= CBIT[c]
        if not opps:
            return ('check', 0) if 'check' in obs.legal else ('call', 0)
        self.hero_draw = False
        if street < 3:
            xx = 0
            rm = 0
            for c in hole:
                xx += CODE[c]
                rm |= RBIT[c]
            for c in board:
                xx += CODE[c]
                rm |= RBIT[c]
            sc = xx >> 40
            fd = ((sc >> (4 * (hole[0] & 3))) & 15) == 4 or ((sc >> (4 * (hole[1] & 3))) & 15) == 4
            self.hero_draw = fd or SD[rm] >= 2
        pools = self._build_pools(obs, opps, known_mask)
        if _perf() - t0 > 0.00045:
            self.slow_skip = True
        weights = {j: self._line_weights(obs, j, pools[j]) for j in opps}
        # MC
        need = 5 - len(board)
        deck = [c for c in range(52) if not (known_mask >> c & 1)]
        hcode = CODE[hole[0]] + CODE[hole[1]]
        for c in board:
            hcode += CODE[c]
        hcards = list(hole) + list(board)
        deadline = t0 + (self.K_DEADLINE if not getattr(self, 'slow_skip', False) else 0.0)
        self.slow_skip = False
        heads_up = len(opps) == 1
        if heads_up:
            j = opps[0]
            ent = pools[j]
            wj = weights[j]
            m = len(ent)
            acc_w = [0.0] * m
            acc_n = [0] * m
            if m == 0:
                return self._safe(obs)
            if need == 0:
                xh = hcode
                vh = flush_val(hcards) if ((xh >> 40) + 0x3333) & 0x8888 else NF[xh & M39]
                for k in range(m):
                    vo = ent[k][5]
                    acc_w[k] = 1.0 if vh > vo else (0.5 if vh == vo else 0.0)
                    acc_n[k] = 1
            else:
                cum = []
                tot = 0.0
                for x in wj:
                    tot += x
                    cum.append(tot)
                K = 170
                idxs = rng.choices(range(m), cum_weights=cum, k=K)
                L = len(deck)
                done = 0
                nf = NF
                C = CODE
                R = _rand
                bl = list(board)
                for k in range(K):
                    if (k & 15) == 15 and _perf() > deadline:
                        break
                    i = idxs[k]
                    e = ent[i]
                    msk = e[3]
                    r1 = deck[int(R() * L)]
                    if (msk >> r1) & 1:
                        continue
                    if need == 2:
                        r2 = deck[int(R() * L)]
                        if r2 == r1 or (msk >> r2) & 1:
                            continue
                        add = C[r1] + C[r2]
                        xh = hcode + add
                        xo = e[2] + add
                        vh = flush_val(hcards + [r1, r2]) if ((xh >> 40) + 0x3333) & 0x8888 else nf[xh & M39]
                        vo = flush_val([e[0], e[1], r1, r2] + bl) if ((xo >> 40) + 0x3333) & 0x8888 else nf[xo & M39]
                    else:
                        add = C[r1]
                        xh = hcode + add
                        xo = e[2] + add
                        vh = flush_val(hcards + [r1]) if ((xh >> 40) + 0x3333) & 0x8888 else nf[xh & M39]
                        vo = flush_val([e[0], e[1], r1] + bl) if ((xo >> 40) + 0x3333) & 0x8888 else nf[xo & M39]
                    acc_n[i] += 1
                    if vh > vo:
                        acc_w[i] += 1.0
                    elif vh == vo:
                        acc_w[i] += 0.5
                    done += 1
                if done < 8:
                    # fall back: current made-hand comparison
                    xh = hcode
                    vh = flush_val(hcards) if ((xh >> 40) + 0x3333) & 0x8888 else NF[xh & M39]
                    for k in range(m):
                        vo = ent[k][5]
                        acc_w[k] += 1.0 if vh > vo else (0.5 if vh == vo else 0.0)
                        acc_n[k] += 1
            return self._decide_hu(obs, j, ent, wj, acc_w, acc_n, pot_total, to_call, my_stack, b)
        # multiway MC
        idx_lists = {}
        for j in opps:
            ent = pools[j]
            wj = weights[j]
            cum = []
            tot = 0.0
            for x in wj:
                tot += x
                cum.append(tot)
            if not ent:
                return self._safe(obs)
            idx_lists[j] = rng.choices(range(len(ent)), cum_weights=cum, k=120)
        wins = 0.0
        cnt = 0
        pos = len(deck)
        L = len(deck)
        bl = list(board)
        for k in range(120):
            if (k & 7) == 7 and _perf() > deadline:
                break
            used = known_mask
            hands = []
            okk = True
            for j in opps:
                e = pools[j][idx_lists[j][k]]
                if used & e[3]:
                    okk = False
                    break
                used |= e[3]
                hands.append(e)
            if not okk:
                continue
            run = []
            for _t in range(need * 3):
                c = deck[int(_rand() * L)]
                if not (used >> c & 1):
                    run.append(c)
                    used |= CBIT[c]
                    if len(run) == need:
                        break
            if len(run) < need:
                continue
            add = 0
            for c in run:
                add += CODE[c]
            xh = hcode + add
            vh = flush_val(hcards + run) if ((xh >> 40) + 0x3333) & 0x8888 else NF[xh & M39]
            best = -1
            nb = 0
            for e in hands:
                xo = e[2] + add
                vo = flush_val([e[0], e[1]] + bl + run) if ((xo >> 40) + 0x3333) & 0x8888 else NF[xo & M39]
                if vo > best:
                    best = vo
                    nb = 1
                elif vo == best:
                    nb += 1
            if vh > best:
                wins += 1.0
            elif vh == best:
                wins += 1.0 / (nb + 1)
            cnt += 1
        if cnt < 6:
            eq = MULTI[hand_class(hole[0], hole[1])][min(7, len(opps)) - 1]
        else:
            eq = wins / cnt
        return self._decide_mw(obs, opps, eq, pot_total, to_call, my_stack, b)

    def _fold_prob(self, j, size_frac, b, vs_me=True):
        o = self.opps[j]
        base = o.rate('fb', 0, b)
        if vs_me:
            base = o.rate('fbme', 0, b, parent=base)
        # size scaling relative to a 0.6-pot reference
        sc = max(0.5, min(1.6, (size_frac / 0.6) ** 0.35))
        return max(0.02, min(0.95, base * sc * self.K_FOLD))

    def _valuer(self, obs, j):
        """Returns VV(my_stack, dj): blended ICM/chip value with seat j's stack changed by dj."""
        me = obs.seat
        n = len(obs.stacks)
        alive = [k for k in range(n) if k != me and (obs.stacks[k] > 0 or obs.in_hand[k])]
        others = [obs.stacks[k] for k in alive]
        idx = alive.index(j) if j in alive else -1
        s0 = obs.stacks[me]
        K = self.K_ICM
        d = max(1, (obs.blinds[1] or 1) * 5)
        slope = (chip_value(s0 + d, others) - chip_value(max(0, s0 - d), others)) / (s0 + d - max(0, s0 - d))
        base = chip_value(s0, others)

        def VV(s, dj=0):
            if idx >= 0 and dj:
                o = list(others)
                o[idx] = max(0, o[idx] + dj)
            else:
                o = others
            v = chip_value(max(0, s), o)
            if K >= 1.0:
                return v
            return K * v + (1 - K) * (base + slope * (s - s0))
        return VV

    def _decide_hu(self, obs, j, ent, wj, acc_w, acc_n, pot_total, to_call, my_stack, b):
        me = obs.seat
        street = obs.street
        rng = self.rng
        m = len(ent)
        num = 0.0
        den = 0.0
        for k in range(m):
            if acc_n[k]:
                num += wj[k] * acc_w[k] / acc_n[k]
                den += wj[k]
        eq = num / den if den > 0 else 0.5
        o = self.opps[j]
        opp_stack = obs.stacks[j]
        ip = self._is_ip(obs, me, j)
        eff_behind = min(my_stack, opp_stack + max(0, obs.bets[j] - obs.bets[me]))
        srt = sorted([k for k in range(m) if acc_n[k]], key=lambda k: -ent[k][4])

        def eq_top_frac(frac):
            target = frac * den
            s = 0.0
            nn = 0.0
            dd = 0.0
            for k in srt:
                wk = wj[k]
                if s >= target:
                    break
                take = wk if s + wk <= target else (target - s)
                s += take
                nn += take * acc_w[k] / acc_n[k]
                dd += take
            return nn / dd if dd > 0 else eq
        VV = self._valuer(obs, j)
        s0 = my_stack
        P = pot_total
        realize = 1.0 if street == 3 else (0.93 if ip else 0.86)
        v_lose_pot = VV(s0, P)          # we give up the pot (fold / lose without more chips)
        v_win_pot = VV(s0 + P, 0)
        if to_call == 0:
            q = eq * realize
            ev_check = q * v_win_pot + (1 - q) * v_lose_pot
            best = ('check', 0)
            best_ev = ev_check
            if 'raise' not in obs.legal or eff_behind <= 0:
                return best
            sizes = (0.5, 0.8, 1.25)
            if eff_behind <= 1.6 * P:
                sizes = (0.5, 0.8, 99.0)
            for sf in sizes:
                bet = min(eff_behind, int(sf * P)) if sf < 50 else eff_behind
                if bet < obs.min_raise:
                    bet = min(obs.min_raise, eff_behind)
                if bet <= 0:
                    continue
                frac = bet / float(max(1, P))
                f = self._fold_prob(j, frac, b)
                c = 1 - f
                ecal = eq_top_frac(c)
                r = max(0.03, min(0.4, o.rate('fb', 2, b)))
                e_r = eq_top_frac(max(0.02, r * c))
                allin = bet >= my_stack * 0.95
                fut = 1.0 if (allin or street == 3) else 0.92
                q = ecal * fut
                v_called = q * VV(s0 + P + bet, -bet) + (1 - q) * VV(s0 - bet, P + bet)
                if not allin and e_r < 0.45:
                    # a share r of continuing hands raise and we give up the bet
                    v_called = (1 - r) * v_called + r * VV(s0 - bet, P + bet)
                ev = f * v_win_pot + c * v_called
                if ev > best_ev:
                    best_ev = ev
                    best = ('raise', obs.bets[me] + bet)
            if best[0] == 'raise' and eq > 0.8 and street < 3 and rng.random() < 0.12 and not ip:
                return ('check', 0)
            return best
        # facing a bet
        x = min(to_call, my_stack)
        allin_call = x >= my_stack
        rc = min(1.05, max(0.70, 0.55 + 0.6 * eq + (0.05 if ip else 0.0)))
        fut = 1.0 if (street == 3 or allin_call or opp_stack == 0) else rc
        q = max(0.0, eq - self.K_CALL) * fut
        implied = 0
        if street < 3 and not allin_call and opp_stack > 0 and self.hero_draw:
            implied = int(0.05 * min(opp_stack, my_stack - x))
        v_fold = v_lose_pot
        ev_call = q * VV(s0 + P + implied, -implied) + (1 - q) * VV(s0 - x, P + x)
        best = ('call', 0)
        best_ev = ev_call
        if 'raise' in obs.legal and opp_stack > 0:
            cur = max(obs.bets)
            for mult in (2.8, 99.0):
                if mult < 50:
                    raise_to = int(cur * mult + 0.3 * P)
                else:
                    raise_to = obs.max_raise
                raise_to = max(obs.min_raise, min(obs.max_raise, raise_to))
                add = raise_to - obs.bets[me]
                their_add = max(0, min(raise_to, obs.bets[j] + opp_stack) - obs.bets[j])
                if add <= x:
                    continue
                f = max(0.03, min(0.85, o.rate('fr', 0, b)))
                committed = obs.bets[j] / float(max(1, obs.bets[j] + opp_stack))
                f *= max(0.2, 1 - committed * 1.5)
                ecal = eq_top_frac(1 - f)
                allin = raise_to >= obs.max_raise * 0.95
                fut2 = 1.0 if (allin or street == 3) else 0.92
                q2 = ecal * fut2
                ev = f * v_win_pot + (1 - f) * (q2 * VV(s0 + P + their_add, -their_add) + (1 - q2) * VV(s0 - add, P + add))
                if ev > best_ev:
                    best_ev = ev
                    best = ('raise', raise_to)
        if best_ev < v_fold:
            return ('fold', 0)
        return best

    def _is_ip(self, obs, me, j):
        n = len(obs.stacks)
        btn = obs.button
        return (me - btn - 1) % n > (j - btn - 1) % n

    def _decide_mw(self, obs, opps, eq, pot_total, to_call, my_stack, b):
        me = obs.seat
        street = obs.street
        nop = len(opps)
        realize = 1.0 if street == 3 else 0.85
        jm = max(opps, key=lambda k: obs.stacks[k] + obs.bets[k])
        if to_call > 0:
            bettor = max(opps, key=lambda k: obs.bets[k])
            jm = bettor
        VV = self._valuer(obs, jm)
        s0 = my_stack
        P = pot_total
        v_win_pot = VV(s0 + P, 0)
        v_lose_pot = VV(s0, P)
        if to_call == 0:
            q = eq * realize
            ev_check = q * v_win_pot + (1 - q) * v_lose_pot
            if 'raise' not in obs.legal:
                return ('check', 0)
            bet = int(0.6 * P)
            eff_behind = min(my_stack, max(obs.stacks[k] for k in opps))
            bet = max(obs.min_raise, min(bet, eff_behind))
            if bet <= 0:
                return ('check', 0)
            frac = bet / float(max(1, P))
            fall = 1.0
            for k in opps:
                fall *= self._fold_prob(k, frac, b)
            ec = eq * (0.78 if eq < 0.7 else 0.92)
            q = ec * 0.95
            ev_bet = fall * v_win_pot + (1 - fall) * (q * VV(s0 + P + bet, -bet) + (1 - q) * VV(s0 - bet, P + bet))
            if ev_bet > ev_check and (eq > 0.5 or fall > 0.4):
                return ('raise', obs.bets[me] + bet)
            return ('check', 0)
        x = min(to_call, my_stack)
        rc = min(1.0, max(0.65, 0.5 + 0.6 * eq))
        fut = 1.0 if street == 3 or x >= my_stack else rc
        q = max(0.0, eq - self.K_CALL) * fut
        ev_call = q * v_win_pot + (1 - q) * VV(s0 - x, P + x)
        if eq > 0.62 and 'raise' in obs.legal:
            cur = max(obs.bets)
            raise_to = int(cur * 3 + 0.3 * P)
            if raise_to > 0.5 * (obs.max_raise):
                raise_to = obs.max_raise
            return ('raise', raise_to)
        if ev_call > v_lose_pot:
            return ('call', 0)
        return ('fold', 0)


try:
    import gc as _gc
    _gc.collect()
    if hasattr(_gc, 'freeze'):
        _gc.freeze()
except Exception:
    pass
